DisenchantValueData = {}
DisenchantValue = {}

-- Since 0.3.0 EverlookDB Auctions (version 5 of its API) does all of this itself: the disenchant log, your results on
-- tooltips, the breakdown and /dv. With it loaded (it loads first: ## OptionalDeps), this addon does nothing but leave
-- its saved log (DisenchantValueDB) for Auctions to take over, and says so once. Every other file stops at its top.
do
  local api = rawget(_G, "EverlookDBAuctionsAPI")
  if api and (tonumber(api.version) or 0) >= 5 then
    DisenchantValue.merged = true
    local f = CreateFrame("Frame")
    f:RegisterEvent("PLAYER_LOGIN")
    f:SetScript("OnEvent", function()
      f:UnregisterEvent("PLAYER_LOGIN")
      local db = type(DisenchantValueDB) == "table" and DisenchantValueDB or nil
      if db and db.movedNotice then return end
      if db then db.movedNotice = true else DisenchantValueDB = { movedNotice = true } end
      print("|cffa335eeDisenchantValue|r is now part of EverlookDB Auctions: /dv still works.")
    end)
  end
end
